    recs = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            d = json.loads(line)
            recs[d['case']] = (d['system'], d['status'], d['note'])
    return recs

def load_csv(path):
    recs = {}
    with open(path, encoding='utf-8', newline='') as f:
        r = csv.DictReader(f)
        for row in r:
            recs[row['case']] = (row['system'], row['status'], row['note'])
    return recs

def load_yaml(path):
    recs = {}
    case = system = status = None
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.rstrip('\n').rstrip('\r')
            if line.startswith('- case: '):
                case = line.split('- case: ')[1].strip()
            elif line.strip().startswith('system: '):
                system = line.strip().split('system: ')[1].strip()
            elif line.strip().startswith('status: '):
                status = line.strip().split('status: ')[1].strip()
