                note = line.strip().split('note: ',1)[1].strip().strip(chr(34))
                recs[case] = (system, status, note)
    return recs

files = {
  'oauth-s05-t04-evidence-01.md': load_md('oauth-s05-t04-evidence-01.md'),
  'oauth-s05-t04-evidence-02.jsonl': load_jsonl('oauth-s05-t04-evidence-02.jsonl'),
