import json, csv, re, itertools

def load_md(path):
    recs = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            m = re.match(r'- \*\*(oauth-s05-t05-\d+)\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.*)', line.strip())
            if m:
                recs[m.group(1)] = (m.group(2), m.group(3), m.group(4))
    return recs

def load_jsonl(path):
    recs = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            d = json.loads(line)
            recs[d['case']] = (d['system'], d['status'], d['note'])
    return recs

def load_csv(path):
    recs = {}
    with open(path, encoding='utf-8', newline='') as f:
        r = csv.DictReader(f)
        for row in r:
            recs[row['case']] = (row['system'], row['status'], row['note'])
    return recs

def load_yaml(path):
    recs = {}
    case = system = status = None
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.rstrip('\n').rstrip('\r')
            if line.startswith('- case: '):
                case = line.split('- case: ')[1].strip()
            elif line.strip().startswith('system: '):
                system = line.strip().split('system: ')[1].strip()
            elif line.strip().startswith('status: '):
                status = line.strip().split('status: ')[1].strip()
            elif line.strip().startswith('note: '):
                note = line.strip().split('note: ',1)[1].strip().strip(chr(34))
                recs[case] = (system, status, note)
    return recs

files = {
  'oauth-s05-t05-evidence-01.md': load_md('oauth-s05-t05-evidence-01.md'),
  'oauth-s05-t05-evidence-02.jsonl': load_jsonl('oauth-s05-t05-evidence-02.jsonl'),
  'oauth-s05-t05-evidence-03.csv': load_csv('oauth-s05-t05-evidence-03.csv'),
  'oauth-s05-t05-evidence-04.yaml': load_yaml('oauth-s05-t05-evidence-04.yaml'),
}

for name, d in files.items():
    print(name, 'records=', len(d))

names = list(files.keys())
for a, b in itertools.combinations(names, 2):
    da, db = files[a], files[b]
    shared = set(da) & set(db)
    mism = sum(1 for k in shared if (da[k][0], da[k][1]) != (db[k][0], db[k][1]))
    print(f'{a} vs {b}: shared={len(shared)} mismatches={mism}')

for name, d in files.items():
    print(name, 'systems=', sorted(set(v[0] for v in d.values())), 'statuses=', sorted(set(v[1] for v in d.values())))
