"""Domain errors mapped to loopback HTTP statuses and error codes."""
from __future__ import annotations


class DomainError(Exception):
    """Base class for errors the HTTP layer turns into JSON error bodies."""

    status: int = 400
    code: str = "malformed_request"

    def __init__(self, message: str | None = None):
        super().__init__(message or self.code)


class MalformedRequest(DomainError):
    status = 400
    code = "malformed_request"


class UnregisteredCallback(DomainError):
    status = 400
    code = "unregistered_callback"


class InvalidCredentials(DomainError):
    status = 403
    code = "invalid_credentials"


class InvalidLogin(DomainError):
    status = 403
    code = "invalid_login"


class InvalidContinuation(DomainError):
    status = 403
    code = "invalid_continuation"


class InvalidAuthorization(DomainError):
    status = 403
    code = "invalid_authorization"


class InvalidCode(DomainError):
    status = 403
    code = "invalid_code"


class WrongClient(DomainError):
    status = 403
    code = "wrong_client"


class UnknownClient(DomainError):
    status = 400
    code = "unknown_client"


class UnknownLogin(DomainError):
    status = 400
    code = "unknown_login"


class CallbackMismatch(DomainError):
    status = 400
    code = "callback_mismatch"


class DuplicatePlan(DomainError):
    status = 409
    code = "duplicate_plan"

"""Shared helpers for oauthsvc tests."""
from __future__ import annotations

import json
import threading
import urllib.error
import urllib.request
from contextlib import contextmanager

from oauthsvc import httpserver


@contextmanager
def running_server(database, signing_key="test-signing-key", code_ttl_seconds=120):
    server = httpserver.create_server(
        database, signing_key, code_ttl_seconds=code_ttl_seconds, port=0
    )
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    try:
        host, port = server.server_address
        yield f"http://{host}:{port}"
    finally:
        server.shutdown()
        thread.join()
        server.server_close()


def post_json(base_url, path, payload):
    body = json.dumps(payload).encode("utf-8")
    return post_raw(base_url, path, body)


def post_raw(base_url, path, raw_body, content_type="application/json"):
    request = urllib.request.Request(
        base_url + path,
        data=raw_body,
        headers={"Content-Type": content_type},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request) as response:
            return response.status, json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        with exc:
            return exc.code, json.loads(exc.read().decode("utf-8"))

