cd "maintenance/inputs/oauth-s05/client-version-matrix" && py -3 - <<'PY'
import json, csv, re, collections

def parse_md(path):
    records = {}
    pattern = re.compile(r'\*\*(oauth-s05-t08-\d+)\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.+)$')
    with open(path, encoding='utf-8') as f:
        for line in f:
            m = pattern.search(line)
            if m:
                case, system, status, note = m.groups()
                records[case] = {"system": system, "status": status, "note": note.strip()}
    return records

def parse_jsonl(path):
    records = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            records[obj["case"]] = {"system": obj["system"], "status": obj["status"], "note": obj["note"]}
    return records

def parse_csv(path):
    records = {}
    with open(path, encoding='utf-8', newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            records[row["case"]] = {"system": row["system"], "status": row["status"], "note": row["note"]}
    return records

def parse_yaml(path):
    records = {}
    with open(path, encoding='utf-8') as f:
        lines = f.readlines()
    cur = {}
    for line in lines:
        line = line.rstrip("\n")
        if line.startswith("- case:"):
            if cur.get("case"):
                records[cur["case"]] = {"system": cur.get("system"), "status": cur.get("status"), "note": cur.get("note")}
            cur = {"case": line.split("- case:")[1].strip()}
        elif line.strip().startswith("system:"):
            cur["system"] = line.split("system:")[1].strip()
        elif line.strip().startswith("status:"):
            cur["status"] = line.split("status:")[1].strip()
        elif line.strip().startswith("note:"):
            note = line.split("note:", 1)[1].strip()
            if note.startswith('"') and note.endswith('"'):
                note = note[1:-1]
            cur["note"] = note
    if cur.get("case"):
        records[cur["case"]] = {"system": cur.get("system"), "status": cur.get("status"), "note": cur.get("note")}
    return records

md = parse_md("oauth-s05-t08-evidence-01.md")
jsonl = parse_jsonl("oauth-s05-t08-evidence-02.jsonl")
csvf = parse_csv("oauth-s05-t08-evidence-03.csv")
yaml = parse_yaml("oauth-s05-t08-evidence-04.yaml")

files = {"md": md, "jsonl": jsonl, "csv": csvf, "yaml": yaml}
for name, recs in files.items():
    ids = sorted(recs.keys())
    dupes = [k for k, v in collections.Counter(recs.keys()).items() if v > 1]
    print(f"{name}: count={len(recs)} min={ids[0]} max={ids[-1]} duplicates={dupes}")

names = list(files.keys())
print("\n--- containment checks ---")
for i in range(len(names)):
    for j in range(len(names)):
        if i == j:
            continue
        a, b = names[i], names[j]
        set_a, set_b = set(files[a].keys()), set(files[b].keys())
        if set_a <= set_b:
            print(f"{a} subset_of {b}: True (size {len(set_a)} <= {len(set_b)})")

print("\n--- pairwise comparison on shared case IDs ---")
for i in range(len(names)):
    for j in range(i+1, len(names)):
        a, b = names[i], names[j]
        shared = set(files[a].keys()) & set(files[b].keys())
        mismatches = 0
        for cid in shared:
            ra, rb = files[a][cid], files[b][cid]
            if ra["system"] != rb["system"] or ra["status"] != rb["status"] or ra["note"] != rb["note"]:
                mismatches += 1
        print(f"{a} vs {b}: shared={len(shared)} mismatches={mismatches}")

print("\n--- distinct (system, status) pairs in csv (largest file) ---")
pairs = set()
for cid, rec in csvf.items():
    pairs.add((rec["system"], rec["status"]))
print(sorted(pairs))

print("\n--- note template / case-number correspondence check (csv, full set) ---")
bad = []
for cid, rec in csvf.items():
    num = int(cid.split("-")[-1])
    if f"case {num}." not in rec["note"]:
        bad.append(cid)
print("mismatched note-number entries:", bad)

print("\n--- md == yaml id sets ---")
print(set(md.keys()) == set(yaml.keys()))

print("\n--- extra IDs in csv beyond md's max ---")
md_max = max(int(c.split("-")[-1]) for c in md)
csv_extra = sorted([c for c in csvf if int(c.split("-")[-1]) > md_max])
print(f"md max case num: {md_max}, csv extra count: {len(csv_extra)}, range: {csv_extra[0]}..{csv_extra[-1]}")

jsonl_max = max(int(c.split("-")[-1]) for c in jsonl)
md_extra = sorted([c for c in md if int(c.split("-")[-1]) > jsonl_max])
print(f"jsonl max case num: {jsonl_max}, md extra beyond jsonl count: {len(md_extra)}, range: {md_extra[0]}..{md_extra[-1]}")
