import json, re, csv

def parse_md(path):
    records = {}
    pat = re.compile(r'\*\*(oauth-s05-t10-\d+)\*\* \| System: (\S+) \| Status: (\S+) \|')
    with open(path, encoding='utf-8') as f:
        for line in f:
            m = pat.search(line)
            if m:
                records[m.group(1)] = {'system': m.group(2), 'status': m.group(3)}
    return records

def parse_jsonl(path):
    records = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            records[obj['case']] = {'system': obj['system'], 'status': obj['status']}
    return records

def parse_csv(path):
    records = {}
    with open(path, encoding='utf-8', newline='') as f:
        for row in csv.DictReader(f):
            records[row['case']] = {'system': row['system'], 'status': row['status']}
    return records

def parse_yaml(path):
    records = {}
    cur = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.rstrip('\n').rstrip('\r')
            if line.startswith('- case:'):
                if cur.get('case'):
                    records[cur['case']] = {'system': cur.get('system'), 'status': cur.get('status')}
                cur = {'case': line.split(':', 1)[1].strip()}
            elif line.strip().startswith('system:'):
                cur['system'] = line.split(':', 1)[1].strip()
            elif line.strip().startswith('status:'):
                cur['status'] = line.split(':', 1)[1].strip()
        if cur.get('case'):
            records[cur['case']] = {'system': cur.get('system'), 'status': cur.get('status')}
    return records

md = parse_md('oauth-s05-t10-evidence-01.md')
jsonl = parse_jsonl('oauth-s05-t10-evidence-02.jsonl')
csvr = parse_csv('oauth-s05-t10-evidence-03.csv')
yaml = parse_yaml('oauth-s05-t10-evidence-04.yaml')

print('md count', len(md))
print('jsonl count', len(jsonl))
print('csv count', len(csvr))
print('yaml count', len(yaml))

mismatches = []
for cid in jsonl:
    for name, recs in [('md', md), ('csv', csvr), ('yaml', yaml)]:
        if cid in recs and recs[cid] != jsonl[cid]:
            mismatches.append((cid, 'jsonl-vs-'+name, jsonl[cid], recs[cid]))
for cid in md:
    if cid in csvr and csvr[cid] != md[cid]:
        mismatches.append((cid, 'md-vs-csv', md[cid], csvr[cid]))
    if cid in yaml and yaml[cid] != md[cid]:
        mismatches.append((cid, 'md-vs-yaml', md[cid], yaml[cid]))

print('mismatches:', len(mismatches))
for m in mismatches[:20]:
    print(m)
