import json, re, csv

def parse_md(path):
    records = {}
    pat = re.compile(r'\*\*(oauth-s05-t11-\d+)\*\* \| System: (\S+) \| Status: (\S+) \|')
    with open(path, encoding='utf-8') as f:
        for line in f:
            m = pat.search(line)
            if m:
                records[m.group(1)] = {'system': m.group(2), 'status': m.group(3)}
    return records

def parse_jsonl(path):
    records = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            records[obj['case']] = {'system': obj['system'], 'status': obj['status']}
    return records

def parse_csv(path):
    records = {}
    with open(path, encoding='utf-8', newline='') as f:
        for row in csv.DictReader(f):
            records[row['case']] = {'system': row['system'], 'status': row['status']}
    return records

def parse_yaml(path):
    records = {}
    cur = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.rstrip('\n').rstrip('\r')
            if line.startswith('- case:'):
                if cur.get('case'):
                    records[cur['case']] = {'system': cur.get('system'), 'status': cur.get('status')}
                cur = {'case': line.split(':', 1)[1].strip()}
            elif line.strip().startswith('system:'):
                cur['system'] = line.split(':', 1)[1].strip()
            elif line.strip().startswith('status:'):
                cur['status'] = line.split(':', 1)[1].strip()
        if cur.get('case'):
            records[cur['case']] = {'system': cur.get('system'), 'status': cur.get('status')}
    return records

md = parse_md('oauth-s05-t11-evidence-01.md')
jsonl = parse_jsonl('oauth-s05-t11-evidence-02.jsonl')
csvr = parse_csv('oauth-s05-t11-evidence-03.csv')
yaml = parse_yaml('oauth-s05-t11-evidence-04.yaml')

print('md count', len(md))
print('jsonl count', len(jsonl))
print('csv count', len(csvr))
print('yaml count', len(yaml))

pairs = [
    ('md-vs-jsonl', md, jsonl),
    ('md-vs-csv', md, csvr),
    ('md-vs-yaml', md, yaml),
    ('jsonl-vs-csv', jsonl, csvr),
    ('jsonl-vs-yaml', jsonl, yaml),
    ('csv-vs-yaml', csvr, yaml),
]
for name, a, b in pairs:
    shared = set(a) & set(b)
    mism = [cid for cid in shared if a[cid] != b[cid]]
    print(name, 'shared:', len(shared), 'mismatches:', len(mism))

# note field case-number check on largest file (csv)
mismatches = 0
with open('oauth-s05-t11-evidence-03.csv', encoding='utf-8', newline='') as f:
    for row in csv.DictReader(f):
        case_num = int(row['case'].split('-')[-1])
        m = re.search(r'for case (\d+)\.', row['note'])
        note_num = int(m.group(1)) if m else None
        if note_num != case_num:
            mismatches += 1
print('csv note-number mismatches:', mismatches)
